(function(){
'use strict';
const C=LabCore,E=esc,id=()=>crypto.randomUUID(),now=()=>new Date().toISOString();
let lab=C.empty(),revision=0,ready=false,dirty=false,conflict=false,saving=null,saveTimer,aiBusy=false;
const originalRender=render,originalSave=save;
const routes={project:['项目与验收','定义采用与爆款的验收口径。'],creators:['达人档案','新建达人，导入过往作品及数据，查看合作建议。'],data:['数据与依据','关联历史素材、营销表现和可核验的产品资料。'],patterns:['共性与公式','比较多篇真实内容，区分共性、差异与适用边界。'],scripts:['脚本工作台','让已有公式，适配一位具体的达人。'],outcomes:['投放复盘','结合上传文案与对应数据，看清哪里好、哪里差、下一篇怎么改。']};
const nav=document.querySelector('nav');nav.insertAdjacentHTML('afterbegin','<button data-view="creators">达人档案</button><button data-view="data">数据与依据</button>');nav.insertAdjacentHTML('beforeend','<button data-view="outcomes">投放复盘</button>');
document.querySelector('main').insertAdjacentHTML('beforeend','<div id="wfSync" role="status"></div>');document.querySelector('#view').insertAdjacentHTML('beforebegin','<div id="wfJob" class="wf-notice hidden" role="status"></div>');
document.body.insertAdjacentHTML('beforeend','<dialog id="wfDialog"><div class="footer-line" style="margin-top:0"><h2 id="wfDialogTitle"></h2><button data-wf="close" aria-label="关闭编辑">✕</button></div><div id="wfDialogBody"></div></dialog>');
document.querySelector('#settingsDialog details').insertAdjacentHTML('beforeend','<p class="note">文案 / 字幕拆解、文本比较和选题建议均在本地浏览器运行，不调用百炼，也不会把正文发送到外部模型服务。视频链接解析与自动转写仍是独立可选功能。</p>');
nav.prepend(nav.querySelector('[data-view=work]'),nav.querySelector('[data-view=formulas]'));
function syncText(text){$('#wfSync').textContent=text}
function msg(text){$('#wfJob').classList.remove('hidden');$('#wfJob').textContent=text}
async function api(path,data,method){if(window.LabBrowserAPI)return window.LabBrowserAPI(path,data,method);if(!isServed())throw Error('请使用本地服务版 http://127.0.0.1:8787。');const r=await fetch(path,{method:method||(data===undefined?'GET':'POST'),headers:{'Content-Type':'application/json','X-Lab-Token':window.__LAB_TOKEN__},body:data===undefined?undefined:JSON.stringify(data),signal:AbortSignal.timeout(70000)});const result=await r.json();if(!r.ok){const err=Error(result.error||'请求失败');err.status=r.status;throw err}return result}
function audit(action,target){lab.audit.push({at:now(),actor:lab.project.actor||'未署名',action,target});lab.audit=lab.audit.slice(-5000)}
function localBackup(){try{localStorage.setItem('blue-workflow-v2',JSON.stringify(lab))}catch{syncText('浏览器备份空间不足，请导出项目备份。')}}
function mark(action,target){if(action)audit(action,target);lab.records=state.records;dirty=true;localBackup();clearTimeout(saveTimer);saveTimer=setTimeout(flush,500);syncText('修改待保存…')}
async function flush(){if(!ready||!dirty||conflict)return;if(saving){await saving;return flush()}const snapshot=JSON.parse(JSON.stringify(lab));dirty=false;saving=(async()=>{try{const r=await api('/api/workspace',{revision,data:snapshot},'PUT');revision=r.revision;syncText('已保存到本机项目库 · 版本 '+revision+' · '+new Date().toLocaleTimeString())}catch(e){dirty=true;if(e.status===409){conflict=true;msg('发现其他页面的新版本。你的编辑已留在本地备份；请点击顶部“完整项目备份”下载，再点“载入最新版本”。')}syncText('未保存：'+e.message)}finally{saving=null}})();await saving;if(dirty&&!conflict)return;}
save=function(){originalSave();if(ready)mark()};
render=function(){if(['patterns','scripts','project'].includes(state.view))state.view='work';if(routes[state.view]){stats();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#pageTitle').textContent=routes[state.view][0];$('#subtitle').textContent=routes[state.view][1];if(!ready){$('#view').innerHTML='<div class="panel empty">正在加载项目库…</div>';return}({project:projectView,creators:creatorsView,data:dataView,patterns:patternsView,scripts:scriptsView,outcomes:outcomesView})[state.view]()}else{if(!state.records.length){stats();$('#pageTitle').textContent='内容素材';$('#view').innerHTML='<div class="panel empty">还没有素材，请从顶部导入内容。</div>';return}originalRender();if(ready&&state.view==='work'){const r=current();$('#view').insertAdjacentHTML('beforebegin','');const panel=$('#view .workspace>section:last-child .pad');if(panel)panel.insertAdjacentHTML('afterbegin','<div class="wf-toolbar"><button class="primary" data-wf="single" data-id="'+E(r.id)+'" '+(r.sample||!r.text.trim()?'disabled':'')+'>开始拆解</button><button data-wf="metric" data-id="'+E(r.id)+'">关联投放数据</button><span class="note">新版 · 本地规则拆解，结果直接显示在此按钮下方。</span></div>');const latest=lab.analyses.filter(a=>a.recordIds.includes(r.id)).at(-1);if(latest&&panel)panel.querySelector('.wf-toolbar').insertAdjacentHTML('afterend',analysisHTML(latest));}}};
function field(name,label,value='',type='text',extra=''){return '<label class="wf-field"><span>'+E(label)+'</span><input name="'+name+'" type="'+type+'" value="'+E(value??'')+'" '+extra+'></label>'}
function area(name,label,value=''){return '<label class="wf-field"><span>'+E(label)+'</span><textarea name="'+name+'">'+E(value)+'</textarea></label>'}
function select(name,label,options,value){return '<label class="wf-field"><span>'+E(label)+'</span><select name="'+name+'">'+options.map(([v,t])=>'<option value="'+E(v)+'" '+(String(value)===String(v)?'selected':'')+'>'+E(t)+'</option>').join('')+'</select></label>'}
function form(kind,key,html){return '<form data-form="'+kind+'" data-id="'+E(key||'')+'">'+html+'<div class="footer-line"><span class="note" data-form-status role="status"></span><button class="primary">保存</button></div></form>'}
function dialog(title,html){$('#wfDialogTitle').textContent=title;$('#wfDialogBody').innerHTML=html;$('#wfDialog').showModal()}
const options={platform:[['星图/抖音','星图 / 抖音'],['小红书','小红书']],group:[['unlabelled','未分组'],['hit','历史爆款组（人工标注）'],['control','普通 / 未达标对照组']],decision:[['pending','待审核'],['direct','直接采用'],['minor','轻微修改后采用'],['major','大幅改写'],['rejected','未采用']]};
function sourceTitle(rid){return state.records.find(r=>r.id===rid)?.title||rid}
function creatorTitle(cid){return lab.creators.find(c=>c.id===cid)?.name||'未关联达人'}
function badge(text){return '<span class="tag">'+E(text)+'</span>'}
function list(items){return '<ul>'+items.map(x=>'<li>'+E(x)+'</li>').join('')+'</ul>'}
function evidenceHTML(items){return items.map(x=>'<blockquote>「'+E(x.quote)+'」<div class="wf-source">来源：'+E(sourceTitle(x.recordId))+'</div></blockquote>').join('')}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function projectView(){const p=lab.project;$('#view').innerHTML='<div class="wf-step">真实历史视频 → 核对字幕及营销数据 → 多篇对照 → 归纳公式 → 选择达人 → 生成脚本 → 记录采用 → 投放回填</div><div class="wf-toolbar"><button data-wf="backup">导出完整项目</button><button data-wf="restore">导入项目备份</button><button data-wf="reload">载入共享版本</button></div>'+form('project','', '<section class="panel pad"><h2>验收口径</h2><p class="note">初始建议：直接采用和轻改计入采用；大改单独记录。设置后用于投放结果统计。</p>'+field('adoptionTarget','采用率目标（严格大于，%）',p.adoptionTarget,'number','min="0" max="100" step="0.1"')+field('hitTarget','爆款率目标（严格大于，%）',p.hitTarget,'number','min="0" max="100" step="0.1"')+field('windowDays','发布后观察期（天）',p.windowDays,'number','min="1" max="365"')+field('minSample','最低验收样本量（建议值，可修改）',p.minSample,'number','min="1" max="1000"')+select('hitMetric','单条内容达到爆款的指标',[['views','播放量'],['collects','收藏数'],['engagementRate','互动率：赞评藏转 / 播放量（%）'],['conversions','转化数']],p.hitMetric)+field('hitThreshold','单条爆款阈值（必须由团队定义）',p.hitThreshold,'number','min="0" step="any"')+'<label><input name="definitionConfirmed" type="checkbox" '+(p.definitionConfirmed?'checked':'')+'> 启用以上爆款率判定口径</label><p class="note">不同批次分别评估；空值不当成零。观察期未满或数据缺失的内容不会被算作成功。</p></section>')+'<section class="panel pad section"><h2>最近协作记录</h2><p class="note">本机项目库支持不同页面共享、冲突检测和文件备份；尚未部署团队登录或公网多人工作空间。</p>'+lab.audit.slice(-12).reverse().map(a=>'<p class="wf-source">'+E(a.at)+' · '+E(a.actor)+' · '+E(a.action)+' · '+E(a.target||'')+'</p>').join('')+'</section>'}
let selectedCreatorId='';
function creatorRecords(c){return state.records.filter(r=>!r.sample&&((c.recordIds||[]).includes(r.id)||lab.metrics.some(m=>m.recordId===r.id&&m.creatorId===c.id)))}
function creatorsView(){const c=lab.creators.find(x=>x.id===selectedCreatorId)||lab.creators[0];if(c)selectedCreatorId=c.id;
$('#view').innerHTML='<div class="wf-toolbar"><button class="primary" data-wf="creator">＋ 新建达人</button>'+lab.creators.map(x=>'<button data-wf="selectCreator" data-id="'+E(x.id)+'" '+(x===c?'class="primary"':'')+'>'+E(x.name)+'</button>').join('')+'</div>'+(c?'<section class="panel pad"><h2>'+E(c.name)+'</h2><p>① 导入这位达人的过往脚本　② 在每篇作品下关联数据　③ 查看下方分析和合作建议</p><div class="actions"><button class="primary" data-wf="creatorWorks" data-id="'+E(c.id)+'">导入过往作品</button><button data-wf="creatorExisting" data-id="'+E(c.id)+'">选择已上传素材</button><button data-wf="creator" data-id="'+E(c.id)+'">修改名称</button></div></section>'+reviewHTML(creatorRecords(c),c):'<section class="panel empty">先点击“新建达人”，填写名称即可。之后在达人下面导入脚本和对应数据。</section>')}
function creatorForm(cid){const c=lab.creators.find(x=>x.id===cid)||{};dialog('达人名称',form('creator',cid,field('name','达人名称',c.name,'text','required maxlength="100"')))}
function creatorWorks(cid){dialog('导入达人过往作品','<form data-creator-import="'+E(cid)+'"><p>每篇脚本导入后单独关联数据，避免把不同作品的数字混在一起。</p><label class="wf-field">上传文档（支持多选）<input name="works" type="file" multiple accept=".docx,.pdf,.txt,.md,.csv,.tsv,.json,.srt,.vtt"></label>'+area('scripts','或粘贴脚本：第一行标题，多篇用单独一行 --- 分隔')+'<p data-import-status role="status"></p><button class="primary">导入并分析</button></form>')}
function reviewHTML(records,creator){
if(!records.length)return '<section class="panel empty section">还没有作品。导入脚本后，在每篇下面上传对应投放文字或截图。</section>';
const valid=(m,k)=>typeof m?.[k]==='number'&&Number.isFinite(m[k]);
const rows=records.map(r=>({r,m:lab.metrics.find(x=>x.recordId===r.id)||{},f:C.keyFactor(r)}));
const summary=['searchRate','newA3Rate'].map(k=>{const set=rows.filter(x=>valid(x.m,k)),pass=set.filter(x=>x.m[k]>=metricTargets[k]);return metricLabels[k]+'：'+pass.length+' / '+set.length+' 篇有数据作品达标，'+(records.length-set.length)+' 篇未提供；目标 '+metricTargets[k]+'%'});
let recommendations=[];
for(const k of ['searchRate','newA3Rate']){const set=rows.filter(x=>valid(x.m,k)).sort((a,b)=>b.m[k]-a.m[k]);if(set.length){const best=set[0];recommendations.push('在已上传作品中，《'+best.r.title+'》的'+metricLabels[k]+'最高，为 '+metricDisplay(k,best.m[k])+'。'+(best.m[k]>=metricTargets[k]?'可优先作为合作参考，保留其“'+best.f.point+'”结构，再替换真实使用情境。':'仍未达到目标，不宜直接复制；先做小范围内容测试。'))}}
if(!recommendations.length)recommendations.push('尚无两项目标指标，不能判断历史作品是否爆款。先补充对应数据，当前仅能提供文本结构建议。');
return '<section class="panel pad section"><h2>'+(creator?'历史作品分析 · '+E(creator.name):'上传内容与投放数据复盘')+'</h2><p>共 '+records.length+' 篇真实作品；分析随作品及关联数据更新。</p>'+list(summary)+'<h3>'+(creator?'之后合作怎么做':'优先保留与调整的方向')+'</h3>'+list(recommendations)+'<p class="note">以下为本地规则分析。指标达标是事实，文案结构是候选解释；不同预算、人群和统计周期的作品不能直接据此判定因果。</p></section>'+rows.map(({r,m,f})=>{
const good=[],bad=[],todo=[];
for(const k of ['searchRate','newA3Rate']){if(!valid(m,k)){bad.push('未提供'+metricLabels[k]+'，无法评价该项表现。');continue}const delta=Number(Math.abs(m[k]-metricTargets[k]).toFixed(4));(m[k]>=metricTargets[k]?good:bad).push(metricLabels[k]+' '+metricDisplay(k,m[k])+'，'+(m[k]>=metricTargets[k]?'达到':'低于')+'目标 '+metricTargets[k]+'%'+(m[k]<metricTargets[k]?'，差 '+delta+' 个百分点':'')+'。')}
good.push('内容可保留的部分（候选）：'+f.point+'。'+f.reason);
if(valid(m,'searchRate')&&m.searchRate<metricTargets.searchRate)todo.push('针对看后搜不足：检查品牌与产品名称是否容易记住，围绕原文“'+f.quote+'”之后增加具体的产品识别信息；保持其他条件相近，比较看后搜变化。');
if(valid(m,'newA3Rate')&&m.newA3Rate<metricTargets.newA3Rate)todo.push('针对新增 A3 率不足：将“'+f.point+'”与产品适用人群、使用动作和可信证据连接，测试更明确的产品表达，观察新增 A3 率。');
if(!todo.length)todo.push('下一篇保留“'+f.point+'”，只替换一个真实场景或开头表达；补齐指标后验证是否可复用。');
bad.push('尚未验证的部分：'+f.test);
return '<article class="panel pad section" data-review-record="'+E(r.id)+'"><h2>'+E(r.title)+'</h2><details><summary>查看上传的脚本原文</summary><p class="wf-block">'+E(r.text)+'</p></details><blockquote>原文线索：'+E(f.quote)+'</blockquote><div class="wf-grid"><section><h3>好在哪 · 表现与可保留点</h3>'+list(good)+'</section><section><h3>差在哪 · 差距与证据缺口</h3>'+list(bad)+'</section></div><h3>下一篇怎么改</h3>'+list(todo)+performanceHTML(r.id)+'<div class="actions"><button data-open="'+E(r.id)+'">查看完整拆解</button>'+(creator?'<button data-wf="unlinkCreator" data-id="'+E(r.id)+'" data-creator="'+E(creator.id)+'">从此达人移出</button>':'')+'</div></article>'}).join('')}
function outcomesView(){$('#view').innerHTML=reviewHTML(state.records.filter(r=>!r.sample&&r.text.trim()))}
document.addEventListener('click',e=>{const b=e.target.closest('[data-wf]');if(!b||!ready)return;const key=b.dataset.id,c=lab.creators.find(x=>x.id===key);
if(b.dataset.wf==='selectCreator'){selectedCreatorId=key;render()}
if(b.dataset.wf==='creatorWorks')creatorWorks(key);
if(b.dataset.wf==='creatorExisting'){const candidates=state.records.filter(r=>!r.sample);dialog('选择此达人的已有作品','<form data-creator-link="'+E(key)+'">'+candidates.map(r=>'<label class="wf-field"><span><input type="checkbox" name="record" value="'+E(r.id)+'" '+(creatorRecords(c).some(x=>x.id===r.id)?'checked':'')+'> '+E(r.title)+'</span></label>').join('')+'<button class="primary">保存关联</button></form>')}
if(b.dataset.wf==='unlinkCreator'){const owner=lab.creators.find(x=>x.id===b.dataset.creator);owner.recordIds=(owner.recordIds||[]).filter(x=>x!==key);lab.metrics.forEach(m=>{if(m.recordId===key&&m.creatorId===owner.id)m.creatorId=''});mark('移出达人作品',key);render()}
});
document.addEventListener('submit',async e=>{const f=e.target,cid=f.dataset.creatorImport||f.dataset.creatorLink;if(!cid)return;e.preventDefault();const c=lab.creators.find(x=>x.id===cid),button=f.querySelector('button');button.disabled=true;try{
if(f.dataset.creatorLink){c.recordIds=[...f.querySelectorAll('[name=record]:checked')].map(x=>x.value);lab.metrics.forEach(m=>{if(m.creatorId===cid&&!c.recordIds.includes(m.recordId))m.creatorId=''})}
else{let incoming=[];for(const file of f.elements.works.files)incoming.push(...await LabImport.read(file));const text=f.elements.scripts.value.trim();if(text)incoming.push(...LabImport.textRows(text, c.name+'的作品'));if(!incoming.length)throw Error('请选择文档或粘贴脚本');if(incoming.length>20)throw Error('每批最多20篇');if(incoming.some(x=>!x.text?.trim()||x.text.length>50000))throw Error('脚本不能为空或超过50000字');const ids=[];for(const item of incoming){let r=state.records.find(x=>!x.sample&&x.title===item.title&&x.text===item.text);if(!r){r=normalize({...item,id:id(),sample:false});state.records.push(r)}ids.push(r.id);if(!lab.analyses.some(a=>a.recordIds.includes(r.id))){const result=C.localTextBreakdown(r);lab.analyses.push({id:id(),recordIds:[r.id],result,inputSnapshot:{records:[{id:r.id,title:r.title,text:r.text}]},createdAt:now(),model:'本地文本规则'});r.analysis={values:result.values,why:result.why,reuse:result.reuse,evidence:result.evidence.map(x=>x.quote).join('；'),engine:'local-rules'}}}c.recordIds=[...new Set([...(c.recordIds||[]),...ids])];originalSave()}
selectedCreatorId=cid;state.view='creators';mark('更新达人作品',cid);$('#wfDialog').close();render();toast('作品已关联，请在每篇下方上传对应数据');
}catch(err){const status=f.querySelector('[data-import-status]');if(status)status.textContent=err.message;else toast(err.message)}finally{button.disabled=false}});

function dataView(){const real=state.records.filter(r=>!r.sample);$('#view').innerHTML='<div class="wf-toolbar"><button data-wf="metric">上传投放文字 / 图片</button><button class="primary" data-wf="knowledge">＋ 产品依据 / 人工拆解</button><button data-wf="import" data-kind="knowledge">导入知识表</button><button data-wf="template" data-kind="knowledge">下载知识模板</button></div><section class="panel"><div class="panel-head"><h2>素材与营销数据</h2><span class="note">按素材 ID 关联；CSV 不会按行号猜测匹配</span></div><div class="wf-scroll"><table class="wf-table"><thead><tr><th>素材 / ID</th><th>达人</th><th>分组</th><th>投放数据 / 目标</th><th>操作</th></tr></thead><tbody>'+real.map(r=>{const m=lab.metrics.find(x=>x.recordId===r.id)||{};return '<tr><td>'+E(r.title)+'<div class="wf-source">'+E(r.id)+'</div></td><td>'+E(creatorTitle(m.creatorId))+'</td><td>'+E(options.group.find(x=>x[0]===m.group)?.[1]||'未分组')+'</td><td>'+E(m.views??'未填')+' / '+E(m.spend??'未填')+['searchRate','newA3Rate'].map(k=>'<div>'+metricLabels[k]+'：'+(m[k]===undefined?'未识别':E(metricDisplay(k,m[k]))+' · '+E(metricTargetText(k,m[k])))+'</div>').join('')+'</td><td><button data-wf="metric" data-id="'+E(r.id)+'">上传 / 识别</button></td></tr>'}).join('')+'</tbody></table></div>'+(!real.length?'<div class="empty">先从顶部导入真实历史内容或视频字幕。</div>':'')+'</section><section class="section"><h2>可引用的知识与团队经验</h2><p class="note">只有已核验的产品依据能作为脚本 RTB；历史人工拆解作为经验输入，不自动变成事实。</p><div class="wf-grid">'+lab.knowledge.map(k=>'<article class="wf-card"><div class="footer-line" style="margin:0"><h3>'+E(k.title)+'</h3>'+badge(k.verified?'已核验':'待核验')+'</div><p>'+E(k.kind==='rtb'?'产品依据':'历史人工拆解')+' · '+E(k.source)+'</p><p class="wf-block">'+E(k.text.slice(0,280))+'</p><p class="wf-source">核验人：'+E(k.owner||'未填')+' · ID：'+E(k.id)+'</p><button data-wf="knowledge" data-id="'+E(k.id)+'">编辑与核验</button></article>').join('')+'</div></section>'}
function metricForm(rid){metricUpload(rid)}

function knowledgeForm(kid){const k=lab.knowledge.find(x=>x.id===kid)||{};dialog('知识与产品依据',form('knowledge',kid,select('kind','资料类型',[['rtb','产品依据 / RTB'],['manual','历史人工拆解']],k.kind||'rtb')+field('title','资料名称',k.title,'text','required')+area('text','完整内容（作为团队核验资料；本地脚本不会自动扩写功效）',k.text)+field('source','来源：文档链接、报告名称或页码',k.source,'text','required')+field('owner','核验人',k.owner)+ '<label><input name="verified" type="checkbox" '+(k.verified?'checked':'')+'> 已核对来源与适用条件</label>'))}

function performanceHTML(recordId){
 const m=lab.metrics.find(x=>x.recordId===recordId);
 const valid=k=>typeof m?.[k]==='number'&&Number.isFinite(m[k]);
 const fields=Object.keys(metricLabels).filter(valid);
 if(!fields.length)return '<section class="wf-card section" data-performance><h3>投放数据分析</h3><p>这篇素材尚未关联可分析的投放数字。</p><button data-wf="metric" data-id="'+E(recordId)+'">上传投放文字 / 图片</button></section>';
 const rates=['searchRate','newA3Rate'].filter(valid),fmt=n=>Number(n.toFixed(4)).toLocaleString();
 const cards=fields.map(k=>{const v=m[k],target=metricTargets[k],delta=v-target;return '<div class="wf-card"><b>'+E(metricLabels[k])+'</b><p style="font-size:23px;font-weight:700">'+E(metricDisplay(k,v))+'</p>'+(target===undefined?'<small>已关联的实际值；未设置达标目标</small>':'<p>'+E(metricTargetText(k,v))+'</p><small>'+(Math.abs(delta)<1e-9?'恰好达到目标':(delta>0?'高于':'低于')+'目标 '+fmt(Math.abs(delta))+' 个百分点')+'</small>')+'</div>'}).join('');
 let conclusion,suggestion;
 if(rates.length===2){const search=m.searchRate>=metricTargets.searchRate,a3=m.newA3Rate>=metricTargets.newA3Rate;
  if(search&&a3){conclusion='看后搜和新增 A3 率均达到目标。';suggestion='保留当前结构作为复用候选，下一篇只替换一个变量，在相近投放条件下验证表现是否稳定。';}
  else if(search){conclusion='看后搜达到目标，但新增 A3 率未达标，两个指标表现不一致。';suggestion='先核对两项指标的统计周期和人群口径；再测试产品卖点是否清楚、使用场景是否相关，观察新增 A3 率是否改善。不能仅凭这两项数据断定问题出在文案。';}
  else if(a3){conclusion='新增 A3 率达到目标，但看后搜未达标。';suggestion='核对品牌及产品名称是否清晰、是否留下值得进一步了解的信息；以不同表达做对照，观察看后搜变化。';}
  else{conclusion='看后搜和新增 A3 率均未达到目标。';suggestion='优先核对受众、预算和观察期，再分别测试开头、产品卖点与使用场景，避免一次改动全部内容。';}
 }else if(rates.length){const k=rates[0];conclusion=metricLabels[k]+(m[k]>=metricTargets[k]?'达到目标。':'未达到目标。')+'另一项目标指标尚未提供，不能判断两项是否同时达标。';suggestion='补充另一项指标，并保持相同统计周期后再比较。';}
 else{conclusion='已关联基础投放数字；缺少看后搜与新增 A3 率，暂不能按这两个目标判断表现。';suggestion='补充两项百分比。播放量、互动数或消耗单独不能证明内容已经成为爆款。';}
 return '<section class="wf-card section" data-performance><h3>投放数据分析</h3><p class="note">根据本篇最新关联数据实时更新 · '+E(m.recognizedAt||'时间未记录')+'</p><div class="wf-grid">'+cards+'</div><h3 class="section">数据结论</h3><p>'+E(conclusion)+'</p><h3 class="section">下一步建议</h3><p>'+E(suggestion)+'</p><p class="note">达标评价针对已设目标；这些数字不能单独证明上方关键因素造成了爆款，仍需留存、评论与同条件对照验证。</p><button data-wf="metric" data-id="'+E(recordId)+'">更新关联数据</button></section>';
}
function analysisHTML(a){
 const source=a.inputSnapshot?.records?.[0]||state.records.find(r=>a.recordIds.includes(r.id))||{text:''};
 const factor=a.result.keyFactor||C.keyFactor(source),recordId=a.recordIds[0];
 const hasMetrics=lab.metrics.some(m=>m.recordId===recordId&&Object.keys(metricLabels).some(k=>typeof m[k]==='number'));
 const labels=a.result.dimensionLabels||['人群','需求时刻','场景','焦虑','欲望','内容钩子','产品角色','RTB','情绪价值','可复用公式'];
 const uncertainties=hasMetrics?(a.result.uncertainties||[]).filter(x=>!/^没有投放表现/.test(x)):(a.result.uncertainties||[]);
 return '<article id="wfCurrentAnalysis" class="wf-card section"><h3>拆解结果 · '+E(a.model||'本机规则分析')+'</h3><section class="formula" data-key-factor><h3>爆款关键因素 · 首要候选</h3><p><b>'+E(factor.point)+'</b></p><p>'+E(factor.reason)+'</p><blockquote>'+E(factor.quote)+'</blockquote><p class="note">这是基于文字线索的候选判断，尚未证明它是爆款原因。验证方法：'+E(factor.test)+'</p></section>'+performanceHTML(recordId)+'<p class="note">文本拆解时间：'+E(a.createdAt)+' · 下列证据引用自正文 / 字幕。</p><div class="wf-grid">'+a.result.values.map((v,i)=>'<div class="wf-card"><b>'+String(i+1).padStart(2,'0')+' '+E(labels[i])+'</b><p>'+E(v)+'</p></div>').join('')+'</div><section class="wf-card"><h3>文本结构观察（非效果归因）</h3><p>'+E(hasMetrics?'投放数字已关联，目标达标情况见上方数据分析。文本结构仍是候选解释，需要同条件对照才能判断其对表现的影响。':a.result.why)+'</p><h3>可复用结构</h3><p>'+E(a.result.reuse)+'</p><h3>不能照搬</h3><p>'+E(a.result.cannotCopy||'原作者经历和效果结论不能直接照搬。')+'</p></section><h3>原文证据</h3>'+evidenceHTML(a.result.evidence)+'<h3>待验证问题</h3>'+list(uncertainties)+'<details><summary>查看生成时输入快照</summary><pre class="wf-block">'+E(JSON.stringify(a.inputSnapshot,null,2))+'</pre></details></article>';
}

function patternsView(){const readyRecords=state.records.filter(r=>!r.sample&&r.text.trim());$('#view').innerHTML='<div class="wf-grid"><section class="panel pad"><h2>选择对照样本</h2><p class="note">一次2–20篇。建议同时选择爆款与普通内容；本地规则只能描述文本共现，不能确认表现成因。</p><div style="max-height:340px;overflow:auto">'+readyRecords.map(r=>{const m=lab.metrics.find(x=>x.recordId===r.id);return '<label class="wf-check"><input type="checkbox" name="compareRecord" value="'+E(r.id)+'"><span>'+E(r.title)+'<br><small>'+E(m?.group==='hit'?'历史爆款组':m?.group==='control'?'普通对照组':'未分组')+' · '+E(m?.platform||'平台未填')+' · '+E(m?.paid||'流量未知')+'</small></span></label>'}).join('')+(!readyRecords.length?'<div class="empty">请先导入真实正文或视频字幕。</div>':'')+'</div><button class="primary section" data-wf="compare">本地比较文本并提炼候选公式</button></section><section class="panel pad"><h2>比较边界</h2><p>本地规则只识别文本里的词句共现，不能据此证明爆款原因。</p><p>不同平台、达人、预算和发布时间仍会影响表现。</p><p class="note">正文只在本机处理；候选公式不会被当作已验证规律。</p></section></div><div class="section">'+lab.patterns.slice().reverse().map(patternHTML).join('')+'</div>'}
function patternHTML(p){return '<article class="wf-card"><div class="footer-line" style="margin:0"><h2>公式版本 · '+E(p.createdAt.slice(0,16))+'</h2>'+badge(p.result.engine==='local-rules'?'本地规则候选':'AI 归纳结果')+'</div><p class="note">来源 '+p.recordIds.length+' 篇 · '+E(p.model)+' · '+E(p.inputDigest.slice(0,12))+'</p><div class="wf-grid"><div><h3>共同出现的元素</h3>'+p.result.common.map(x=>'<p><b>'+E(x.finding)+'</b></p>'+evidenceHTML(x.evidence)+'<p class="note">'+E(x.boundary)+'</p>').join('')+'</div><div><h3>差异与特性</h3>'+p.result.differences.map(x=>'<p><b>'+E(x.finding)+'</b></p>'+evidenceHTML(x.evidence)+'<p class="note">'+E(x.boundary)+'</p>').join('')+'</div></div>'+p.result.formulas.map((f,i)=>'<section class="formula"><h3>'+E(f.name)+'</h3><p><b>达人类型：</b>'+E(f.creatorTypes.join(' / '))+'　<b>场景：</b>'+E(f.scenes.join(' / '))+'</p><p><b>人群：</b>'+E(f.audience)+'　<b>痛点：</b>'+E(f.pain)+'</p><p><b>内容钩子：</b>'+E(f.hook)+'</p><p><b>结构：</b>'+E(f.structure.join(' → '))+'</p><p><b>可变：</b>'+E(f.variables.join('；'))+'</p><p><b>不能照搬：</b>'+E(f.avoid.join('；'))+'</p><p><b>适用边界：</b>'+E(f.boundary)+'</p><p class="wf-source">来源：'+E(f.sourceIds.map(sourceTitle).join('；'))+'<br>RTB：'+E(f.rtbAssetIds.map(a=>lab.knowledge.find(k=>k.id===a)?.title||a).join('；')||'待补充核验依据')+'</p></section>').join('')+'<p class="note">限制：'+E(p.result.limitations.join('；'))+'</p><div class="actions"><button data-wf="patternExport" data-id="'+E(p.id)+'">导出本版公式</button></div>'+(p.review?'<p class="note">'+E(p.review.actor)+' · '+E(p.review.at)+' · '+E(p.review.note)+'</p>':'')+'<details><summary>输入快照（可追溯生成依据）</summary><pre class="wf-block">'+E(JSON.stringify(p.inputSnapshot,null,2))+'</pre></details></article>'}
function scriptsView(){const choices=lab.patterns.flatMap(p=>p.result.formulas.map((f,i)=>[p.id+'|'+i,f.name+' · '+p.createdAt.slice(0,10)]));$('#view').innerHTML='<section class="panel pad"><h2>选择达人与公式</h2><div class="wf-grid">'+select('scriptCreator','目标达人',[['','请选择'],...lab.creators.map(c=>[c.id,c.name+' / '+c.type])],'')+select('scriptFormula','候选公式',[['','请选择'],...choices],'')+'</div><div id="matchHint" class="note">选择后显示达人档案匹配线索；规则无法判断真实账号表现。</div><button class="primary" data-wf="scripts">生成3条本地脚本变体</button><p class="note">占位处需由达人据实补全。无产品依据时不写功效承诺；正文在本地处理，不调用百炼。</p></section><div class="section">'+lab.scripts.slice().reverse().map(scriptHTML).join('')+'</div>'}
function scriptHTML(s){return '<article class="wf-card wf-script"><div class="footer-line" style="margin:0"><h2>'+E(s.title)+'</h2>'+badge('V'+s.version+' · '+(options.decision.find(x=>x[0]===s.review?.decision)?.[1]||'未记录采用情况'))+'</div><p>'+E(creatorTitle(s.creatorId))+' · '+E(s.cohort)+' · '+E(s.origin==='ai'?'AI生成':s.origin==='rules'?'本地规则候选':'人工修订')+'</p><p><b>匹配理由：</b>'+E(s.matchReason)+'</p><p><b>选题：</b>'+E(s.topic)+'</p><p><b>开头：</b>'+E(s.hook)+'</p><details><summary>完整分镜与口播</summary>'+s.segments.map(seg=>'<div class="wf-segment"><b>'+E(seg.time)+'</b><div><b>画面建议</b><p>'+E(seg.visual)+'</p><small>'+E(seg.productRole)+'</small></div><div><b>口播</b><p>'+E(seg.voiceover)+'</p></div></div>').join('')+'<p><b>结尾：</b>'+E(s.cta)+'</p><p><b>验证：</b>'+E(s.testPlan)+'</p><p class="note">审核点：'+E(s.risks.join('；'))+'</p></details><div class="actions"><button data-wf="scriptReview" data-id="'+E(s.id)+'">记录采用情况</button><button data-wf="scriptEdit" data-id="'+E(s.id)+'">修订新版本</button><button data-wf="release" data-id="'+E(s.id)+'">回填投放</button><button data-wf="scriptExport" data-id="'+E(s.id)+'">导出脚本</button></div>'+(s.review?.actor?'<p class="note">审核：'+E(s.review.actor)+' · '+E(s.review.note||'')+'</p>':'')+'</article>'}
function scriptText(s){return [s.title,'达人：'+creatorTitle(s.creatorId),'版本：'+s.version,'匹配：'+s.matchReason,'选题：'+s.topic,'开头：'+s.hook,...s.segments.map(x=>x.time+'\n画面：'+x.visual+'\n口播：'+x.voiceover+'\n产品：'+x.productRole),'结尾：'+s.cta,'验证：'+s.testPlan,'审核点：'+s.risks.join('；')].join('\n\n')}
function reviewForm(kind,rid){const row=lab.scripts.find(x=>x.id===rid);dialog('采用情况（可选记录）',form('scriptReview',rid,select('decision','采用结论',options.decision,row.review?.decision||'pending')+field('actor','记录人（可选）',row.review?.actor||lab.project.actor)+area('note','备注（可选）',row.review?.note))) }
function releaseForm(sid){const s=lab.scripts.find(x=>x.id===sid),r=s.release||{};dialog('投放结果 · '+s.title,form('release',sid,'<p class="note">只回填该脚本实际发布的内容。数据截点必须达到项目观察期才能计入爆款率。</p>'+field('url','发布链接',r.url,'url')+'<div class="wf-grid">'+field('publishedAt','发布日期',r.publishedAt,'date')+field('observedAt','数据截点日期',r.observedAt,'date')+['views','likes','comments','collects','shares','conversions','spend'].map((k,i)=>field(k,['播放量','点赞','评论','收藏','转发','转化数','投放金额（元）'][i],r[k],'number','min="0" step="any"')).join('')+'</div>'+area('source','数据来源 / 回填说明',r.source))) }
const headers={creators:['creator_id','name','type','platform','followers','audience','style','examples','constraints'],metrics:['record_id','creator_id','group','platform','paid','published_at','observed_at','views','likes','comments','collects','shares','conversions','spend','source'],knowledge:['id','title','kind','text','source','owner']};
function importDialog(kind){dialog('导入'+({creators:'达人档案',metrics:'营销数据',knowledge:'知识资料'}[kind]),'<p class="note">支持 UTF-8 CSV 或直接粘贴表格（制表符分隔）。空数字保留为空；未知素材、达人 ID 或重复关联会阻止整批导入。</p><p class="wf-source">表头：'+E(headers[kind].join(', '))+'</p>'+form('import',kind,'<label class="wf-field"><span>CSV 文件（可选）</span><input type="file" name="csvfile" accept=".csv,.tsv,.txt"></label>'+area('csv','或粘贴含表头的表格')+'<p class="note">ID 对应已有记录时更新，同批重复 ID 不允许。知识导入后统一为待核验。</p>'))}
function importRows(kind,rows){const ids=new Set(),result=[];for(let i=0;i<rows.length;i++){const x=rows[i],prefix='第 '+(i+2)+' 行：';try{if(kind==='creators'){if(!x.creator_id||!x.name||!x.type)throw Error('缺少 creator_id / name / type');result.push({id:x.creator_id,name:x.name,type:x.type,platform:x.platform||'星图/抖音',followers:C.num(x.followers,'粉丝数'),audience:x.audience||'',style:x.style||'',examples:x.examples||'',constraints:x.constraints||''})}else if(kind==='metrics'){if(!state.records.some(r=>r.id===x.record_id&&!r.sample))throw Error('record_id 未匹配真实素材');if(x.creator_id&&!lab.creators.some(c=>c.id===x.creator_id))throw Error('creator_id 不存在');if(!['hit','control','unlabelled'].includes(x.group))throw Error('group 应为 hit、control 或 unlabelled');const m={id:lab.metrics.find(m=>m.recordId===x.record_id)?.id||id(),recordId:x.record_id,creatorId:x.creator_id||'',group:x.group,platform:x.platform||'',paid:x.paid||'unknown',publishedAt:C.date(x.published_at,'发布日期'),observedAt:C.date(x.observed_at,'数据截点'),source:x.source||''};for(const k of ['views','likes','comments','collects','shares','conversions','spend'])m[k]=C.num(x[k],k);if(m.publishedAt&&m.observedAt&&m.observedAt<m.publishedAt)throw Error('数据截点早于发布');result.push(m)}else{if(!x.id||!x.title||!x.text||!x.source)throw Error('缺少 id/title/text/source');if(!['rtb','manual'].includes(x.kind))throw Error('kind 应为 rtb 或 manual');result.push({id:x.id,title:x.title,text:x.text,source:x.source,kind:x.kind,owner:x.owner||'',verified:false})}const key=kind==='metrics'?result.at(-1).recordId:result.at(-1).id;if(ids.has(key))throw Error('同批存在重复 ID');ids.add(key)}catch(e){throw Error(prefix+e.message)}}return result}
async function aiTask(kind,args){if(aiBusy)throw Error('已有文本任务运行');aiBusy=true;try{msg('正在本机整理文本；正文不会发送给百炼或外部模型…');const records=(args.recordIds||[]).map(rid=>state.records.find(r=>r.id===rid)).filter(r=>r&&!r.sample&&r.text.trim());if(kind==='single'&&records.length!==1)throw Error('请选择一篇有正文的真实内容');if(kind==='compare'&&(records.length<2||records.length>20))throw Error('请选择2–20篇有正文的真实内容');let result,recordIds=records.map(r=>r.id),creatorId,patternId,formulaIndex,inputSnapshot;if(kind==='single')result=C.localTextBreakdown(records[0]);else if(kind==='compare')result=C.localTextComparison(records);else if(kind==='script'){patternId=args.patternId;formulaIndex=args.formulaIndex;const pattern=lab.patterns.find(p=>p.id===patternId),formula=pattern?.result.formulas?.[formulaIndex],creator=lab.creators.find(c=>c.id===args.creatorId);if(!pattern||!formula||!creator)throw Error('请先选择达人和已有公式');creatorId=creator.id;recordIds=pattern.recordIds;const sourceRecords=recordIds.map(rid=>state.records.find(r=>r.id===rid)).filter(Boolean);result=C.localScriptSuggestions(creator,formula);inputSnapshot={creator,formula,records:sourceRecords.map(r=>({id:r.id,title:r.title,text:r.text}))}}else throw Error('未知本地文本任务');inputSnapshot=inputSnapshot||{records:records.map(r=>({id:r.id,title:r.title,text:r.text}))};const job={id:id(),kind,recordIds,result,inputSnapshot,inputDigest:C.digest(inputSnapshot),createdAt:now(),model:'本地文本规则（未调用外部服务）',creatorId,patternId,formulaIndex};applyAI(job);if(kind==='single')document.querySelector('#wfCurrentAnalysis')?.scrollIntoView({behavior:'smooth',block:'start'});flush();const syncWarning=dirty||conflict?' 拆解已显示并保存在此浏览器；项目库同步仍待解决。':'';msg((kind==='single'?'本地十维拆解已完成，结果已滚动显示在当前页面下方。':kind==='compare'?'本地文本比较与候选公式已生成。':'本地脚本变体已生成；占位处需由达人据实补全。')+syncWarning)}finally{aiBusy=false}}
window.addEventListener('lab-text-imported',async e=>{const ids=Array.isArray(e.detail)?e.detail:[];try{for(let i=0;i<50&&!ready;i++)await new Promise(resolve=>setTimeout(resolve,100));if(!ready)throw Error('项目库仍在加载，请稍后刷新页面再导入');for(const recordId of ids){const r=state.records.find(x=>x.id===recordId);if(!r||r.sample||!r.text.trim())continue;const existing=lab.analyses.some(a=>a.recordIds.includes(r.id)&&a.inputSnapshot?.records?.some(s=>s.id===r.id&&s.text===r.text));if(existing)continue;await aiTask('single',{recordIds:[r.id]})}if(ids.length)msg('导入内容已完成本地拆解。每篇结果显示在文案详情下方；正文未发送到百炼。')}catch(err){msg('自动拆解未完成：'+err.message);toast('自动拆解未完成：'+err.message)}});
function applyAI(job){if(lab.analyses.some(a=>a.id===job.id)||lab.patterns.some(p=>p.id===job.id)||lab.scripts.some(s=>s.jobId===job.id))return;const base={id:job.id,recordIds:job.recordIds,result:job.result,inputSnapshot:job.inputSnapshot,inputDigest:job.inputDigest,createdAt:job.createdAt,model:job.model};if(job.kind==='single'){lab.analyses.push(base);const r=state.records.find(r=>r.id===job.recordIds[0]);if(r){r.analysis={family:'本地文本结构候选',values:job.result.values,why:job.result.why,reuse:job.result.reuse,evidence:job.result.evidence.map(e=>e.quote).join('；'),engine:'local-rules'};r.approved=false;originalSave()}state.view='work';state.selected=r?.id||state.selected}else if(job.kind==='compare'){lab.patterns.push({...base,review:{approved:false}});state.view='patterns'}else{job.result.scripts.forEach(s=>{const sid=id();lab.scripts.push({...s,id:sid,rootId:sid,version:1,origin:'rules',jobId:job.id,creatorId:job.creatorId,patternId:job.patternId,formulaIndex:job.formulaIndex,matchReason:job.result.matchReason,cohort:lab.project.cohort,createdAt:now(),model:job.model,inputSnapshot:job.inputSnapshot,inputDigest:job.inputDigest,review:{decision:'pending'},release:{}})});state.view='scripts'}mark('本地文本分析完成',job.kind);render()}
document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const button=f.querySelector('button[type=submit],button.primary');button.disabled=true;const get=n=>f.elements.namedItem(n)?.value?.trim()||'',check=n=>!!f.elements.namedItem(n)?.checked;const kind=f.dataset.form,key=f.dataset.id;try{if(!ready)throw Error('项目尚未加载');if(kind==='project'){const previous=JSON.stringify(lab.project);const p={...lab.project};for(const k of ['adoptionTarget','hitTarget','windowDays','minSample']){p[k]=C.num(get(k),k);if(p[k]===null)throw Error('验收参数不能为空')}if(p.adoptionTarget>100||p.hitTarget>100||!Number.isInteger(p.windowDays)||p.windowDays<1||p.windowDays>365||!Number.isInteger(p.minSample)||p.minSample<1||p.minSample>1000)throw Error('验收参数超出范围');p.hitMetric=get('hitMetric');p.hitThreshold=C.num(get('hitThreshold'),'阈值');p.definitionConfirmed=check('definitionConfirmed');if(p.definitionConfirmed&&p.hitThreshold===null)throw Error('确认口径前请填写爆款阈值');lab.project=p;audit('口径修改前快照',previous)}
else if(kind==='creator'){const c={...(lab.creators.find(x=>x.id===key)||{}),id:key||id(),name:get('name'),type:lab.creators.find(x=>x.id===key)?.type||'未分类'};if(!c.name)throw Error('请填写达人名称');upsert('creators',c);selectedCreatorId=c.id;state.view='creators'}
else if(kind==='knowledge'){const k={id:key||id(),kind:get('kind'),title:get('title'),text:get('text'),source:get('source'),owner:get('owner'),verified:check('verified')};if(!k.title||!k.text||!k.source)throw Error('名称、内容和来源不能为空');if(k.verified&&!k.owner)throw Error('核验资料需要填写核验人');upsert('knowledge',k)}
else if(kind==='metric'||kind==='release'){const m={publishedAt:C.date(get('publishedAt'),'发布日期'),observedAt:C.date(get('observedAt'),'数据截点'),source:get('source')};for(const k of ['views','likes','comments','collects','shares','conversions','spend'])m[k]=C.num(get(k),k);if(m.publishedAt&&m.observedAt&&m.observedAt<m.publishedAt)throw Error('数据截点不能早于发布日期');if(m.publishedAt>now().slice(0,10)||m.observedAt>now().slice(0,10))throw Error('实际数据日期不能在未来');if(kind==='metric')upsert('metrics',{...m,id:lab.metrics.find(m=>m.recordId===key)?.id||id(),recordId:key,creatorId:get('creatorId'),platform:get('platform'),paid:get('paid'),group:get('group')});else{m.url=get('url');if(m.publishedAt&&!m.url)throw Error('请填写实际发布链接');lab.scripts.find(s=>s.id===key).release=m}}

else if(kind==='scriptReview'){const row=lab.scripts.find(s=>s.id===key);row.review={decision:get('decision'),actor:get('actor'),note:get('note'),at:now()}}
else if(kind==='scriptEdit'){const old=lab.scripts.find(s=>s.id===key);const segments=old.segments.map((x,i)=>({time:get('time'+i),visual:get('visual'+i),voiceover:get('voiceover'+i),productRole:get('productRole'+i),evidenceAssetIds:x.evidenceAssetIds||[]}));if(!get('title')||segments.some(x=>!x.time||!x.visual||!x.voiceover))throw Error('请保留标题和每一段的时间、画面、口播');const root=old.rootId||old.id;lab.scripts.push({...old,title:get('title'),topic:get('topic'),hook:get('hook'),cta:get('cta'),testPlan:get('testPlan'),segments,id:id(),rootId:root,version:Math.max(...lab.scripts.filter(s=>(s.rootId||s.id)===root).map(s=>s.version))+1,origin:'manual',createdAt:now(),review:{decision:'pending'},release:{}})}
else if(kind==='import'){let text=get('csv');const file=f.elements.namedItem('csvfile').files[0];if(file){if(file.size>3000000)throw Error('文件请小于3MB');text=await file.text()}const incoming=importRows(key,C.csv(text));incoming.forEach(row=>upsert(key,row));toast('已校验并导入 '+incoming.length+' 行')}
mark('保存 '+kind,key);await flush();if(dirty)throw Error('修改已留在本地，但未保存到项目库；请按页面提示处理');if($('#wfDialog').open)$('#wfDialog').close();render();toast('已保存')}catch(err){f.querySelector('[data-form-status]').textContent=err.message}finally{button.disabled=false}});
function upsert(key,row){const i=lab[key].findIndex(x=>x.id===row.id);if(i>=0)lab[key][i]=row;else lab[key].push(row)}
document.addEventListener('click',async e=>{const b=e.target.closest('button[data-wf]');if(!b)return;const action=b.dataset.wf,key=b.dataset.id;try{if(action==='close'){$('#wfDialog').close();return}if(!ready)throw Error('请等待项目加载');if(action==='creator')creatorForm(key);if(action==='metric')metricForm(key);if(action==='knowledge')knowledgeForm(key);if(action==='scriptReview')reviewForm(action,key);if(action==='release')releaseForm(key);if(action==='backup')download('蓝胖子完整项目-'+now().slice(0,10)+'.json',{schemaVersion:2,revision,data:lab});if(action==='patternExport')download('蓝胖子公式-'+key+'.json',lab.patterns.find(p=>p.id===key));if(action==='scriptExport')download('蓝胖子脚本-'+key+'.txt',scriptText(lab.scripts.find(s=>s.id===key)),'text/plain');if(action==='template')download(b.dataset.kind+'-模板.csv','\uFEFF'+headers[b.dataset.kind].join(',')+'\r\n','text/csv');if(action==='import')importDialog(b.dataset.kind);if(action==='restore'){dialog('导入完整项目备份','<p class="note">将替换本机项目库；先导出当前备份。密钥不会受影响。</p><input id="wfRestoreFile" type="file" accept=".json"><button data-wf="restoreApply" class="primary">校验并恢复</button>')};if(action==='restoreApply'){const file=$('#wfRestoreFile').files[0];if(!file)throw Error('请选择备份');if(file.size>5000000)throw Error('文件超过5MB');const value=JSON.parse(await file.text()),data=value.data;if(!data||data.schemaVersion!==2||!Array.isArray(data.records))throw Error('不是完整项目备份');if(!confirm('用此备份替换当前项目？原文件会由服务保留备份。'))return;const result=await api('/api/workspace',{revision,data},'PUT');lab=data;state.records=lab.records.map(normalize);lab.records=state.records;state.selected=state.records.filter(r=>!r.sample&&r.text.trim()).at(-1)?.id||state.records[0]?.id;revision=result.revision;dirty=false;conflict=false;localBackup();originalSave();$('#wfDialog').close();render()};if(action==='reload'){if(dirty||conflict)download('蓝胖子未同步修改.json',{schemaVersion:2,data:lab});const loaded=await api('/api/workspace');lab=loaded.data;revision=loaded.revision;state.records=lab.records;state.selected=state.records.filter(r=>!r.sample&&r.text.trim()).at(-1)?.id||state.records[0]?.id;dirty=false;conflict=false;localBackup();originalSave();render();syncText('已载入项目库版本 '+revision)}if(action==='single')await aiTask('single',{recordIds:[key]});if(action==='compare'){const ids=[...document.querySelectorAll('[name=compareRecord]:checked')].map(x=>x.value);if(ids.length<2||ids.length>20)throw Error('请选择2–20篇真实内容');await aiTask('compare',{recordIds:ids})}if(action==='scripts'){const creatorId=$('[name=scriptCreator]').value,[patternId,index]=$('[name=scriptFormula]').value.split('|');if(!creatorId||!patternId)throw Error('请选择达人和公式');await aiTask('script',{creatorId,patternId,formulaIndex:Number(index)})}if(action==='scriptEdit'){const s=lab.scripts.find(s=>s.id===key);dialog('修订新版本（旧版本保留）',form('scriptEdit',key,field('title','脚本标题',s.title,'text','required')+area('topic','选题',s.topic)+area('hook','开头',s.hook)+s.segments.map((x,i)=>'<section class="wf-card"><h3>第 '+(i+1)+' 段</h3>'+field('time'+i,'时间段',x.time)+area('visual'+i,'画面建议',x.visual)+area('voiceover'+i,'具体口播',x.voiceover)+area('productRole'+i,'产品出现方式',x.productRole)+'</section>').join('')+area('cta','结尾引导',s.cta)+area('testPlan','验证计划',s.testPlan)))}}catch(err){toast(err.message);if(['single','compare','scripts'].includes(action))msg(err.message)}});
document.addEventListener('change',e=>{if(!['scriptCreator','scriptFormula'].includes(e.target.name))return;if(e.target.name==='scriptCreator'){const creator=lab.creators.find(c=>c.id===e.target.value);if(creator){const choices=lab.patterns.flatMap(p=>p.result.formulas.map((f,i)=>({value:p.id+'|'+i,label:f.name,match:f.creatorTypes.some(t=>t.includes(creator.type)||creator.type.includes(t))}))).sort((a,b)=>Number(b.match)-Number(a.match));const chooser=$('[name=scriptFormula]');chooser.innerHTML='<option value="">请选择</option>'+choices.map(x=>'<option value="'+E(x.value)+'">'+E((x.match?'类型匹配 · ':'')+x.label)+'</option>').join('');if(choices[0]?.match)chooser.value=choices[0].value;}}const c=lab.creators.find(c=>c.id===$('[name=scriptCreator]').value),[pid,n]=$('[name=scriptFormula]').value.split('|');const f=lab.patterns.find(p=>p.id===pid)?.result.formulas?.[Number(n)];if(c&&f)$('#matchHint').textContent='达人类型：'+c.type+'；公式建议：'+f.creatorTypes.join(' / ')+'。'+(f.creatorTypes.some(t=>t.includes(c.type)||c.type.includes(t))?'类型文字匹配；仍需核对风格与场景。':'类型文字未直接匹配，请谨慎选择，本地规则仅提供文本线索。')});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
async function init(){try{const loaded=await api('/api/workspace');revision=loaded.revision;lab=loaded.data;if(!lab.records.length&&!revision){lab.records=state.records}else{state.records=lab.records.map(normalize);lab.records=state.records;state.selected=state.records.filter(r=>!r.sample&&r.text.trim()).at(-1)?.id||state.records[0]?.id;originalSave()}ready=true;if(!localStorage.getItem('blue-workflow-welcome')){state.view='work';localStorage.setItem('blue-workflow-welcome','1')}if(!revision)mark('初始化项目库','保留已有素材');render();syncText('本机项目库已加载 · 文案拆解在本地浏览器运行');localStorage.removeItem('blue-workflow-ai-job');const pending=state.records.filter(r=>!r.sample&&r.text.trim()&&!lab.analyses.some(a=>a.recordIds.includes(r.id)&&a.inputSnapshot?.records?.some(s=>s.id===r.id&&s.text===r.text))).slice(0,20).map(r=>r.id);if(pending.length)window.dispatchEvent(new CustomEvent('lab-text-imported',{detail:pending}))}catch(e){ready=false;msg('项目库未连接：'+e.message+'。原有文案工具仍可使用。')}}

let metricDraft=null;
const metricTargets={searchRate:0.35,newA3Rate:8};
function metricDisplay(k,v){return v.toLocaleString()+((k in metricTargets)?'%':'')}
function metricTargetText(k,v){return k in metricTargets?'目标 ≥ '+metricTargets[k]+'% · '+(v>=metricTargets[k]?'已达标':'未达标'):''}
const metricLabels={searchRate:'看后搜',newA3Rate:'新增 A3 率',views:'播放 / 曝光量',likes:'点赞',comments:'评论',collects:'收藏',shares:'分享 / 转发',conversions:'成交 / 转化数',spend:'投放金额（元）'};
function metricUpload(rid){
 const real=state.records.filter(r=>!r.sample);if(!real.length){toast('请先导入一篇真实文案');return;}
 const selected=rid||real[0].id;const old=lab.metrics.find(m=>m.recordId===selected);
 metricDraft=null;
 dialog('上传投放数据',select('metricRecord','关联素材',real.map(r=>[r.id,r.title]),selected)+'<p class="note">粘贴投放报告文字，或上传 TXT、PNG、JPG、WEBP、BMP。图片在本机识别，不调用百炼。每次关联一篇素材；请使用单篇数据截图。看后搜目标 ≥ 0.35%，新增 A3 率目标 ≥ 8%。</p><input id="metricFiles" type="file" accept=".txt,image/png,image/jpeg,image/webp,image/bmp" multiple><p id="metricReadStatus" role="status"></p><textarea id="metricRaw" rows="8" placeholder="例如：播放量 12.5万，点赞 3200，评论 186，收藏 950，消耗 2000元">'+E(old?.rawText||'')+'</textarea><div class="actions"><button class="primary" data-wf="metricRecognize">识别文字中的数据</button></div><div id="metricPreview"></div>');if(old?.rawText)recognizeMetrics();
}
function recognizeMetrics(){
 const raw=$('#metricRaw').value;metricDraft={...C.parseMetricText(raw),raw};
 const entries=Object.entries(metricDraft.values);
 $('#metricPreview').innerHTML='<h3>识别结果</h3>'+(!entries.length?'<p>未识别到明确数字。请在文字中保留指标名称和数字，例如“播放量 12万”。</p>':'<div class="wf-grid">'+entries.map(([k,v])=>'<div class="wf-card"><b>'+metricLabels[k]+'</b><p>'+E(metricDisplay(k,v))+'</p><p>'+E(metricTargetText(k,v))+'</p><small>'+E(metricDraft.evidence[k])+'</small></div>').join('')+'</div>')+metricDraft.warnings.map(w=>'<p>'+E(w)+'</p>').join('')+'<p class="note">核对数字后保存。识别有误可直接修改上方文字再识别；未识别字段不会填成零，也不会覆盖已有数字。</p>'+(entries.length?'<button class="primary" data-wf="metricSave">保存识别结果到这篇素材</button>':'');
}
document.addEventListener('change',async e=>{
 if(e.target.id!=='metricFiles')return;const files=[...e.target.files];const target=$('#metricRaw'),status=$('#metricReadStatus');
 e.target.disabled=true;
 try{for(const f of files){if(f.size>3500000)throw Error('单个文件请小于 3.5 MB');status.textContent='正在读取 '+f.name+'…';let text;
 if(/\.txt$/i.test(f.name))text=await f.text();else{const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f)});text=(await api('/api/recognize-image',{image})).text;}
 if(!text?.trim())throw Error('没有识别到文字，请换清晰截图');target.value+=(target.value?'\n':'')+text;}
 status.textContent='读取完成，请核对识别结果';recognizeMetrics();
 }catch(err){status.textContent=err.message}finally{e.target.disabled=false}
});
document.addEventListener('click',e=>{const b=e.target.closest('button[data-wf]');if(!b)return;try{
 if(b.dataset.wf==='metricRecognize')recognizeMetrics();
 if(b.dataset.wf==='metricSave'){
  if(!metricDraft||metricDraft.raw!==$('#metricRaw').value)throw Error('文字已修改，请先重新识别');
  const recordId=$('[name=metricRecord]').value;if(!state.records.some(r=>r.id===recordId))throw Error('关联素材已不存在');
  const old=lab.metrics.find(x=>x.recordId===recordId)||{id:id(),recordId,group:'unlabelled',paid:'unknown',creatorId:'',platform:'',publishedAt:'',observedAt:''};
  upsert('metrics',{...old,...metricDraft.values,rawText:metricDraft.raw,source:'用户上传文字 / 本机图片识别',recognizedAt:now()});mark('识别投放数据',recordId);$('#wfDialog').close();render();toast('投放数据已关联');
 }
 if(b.dataset.wf==='toggleHitLibrary'){const r=state.records.find(r=>r.id===b.dataset.id);if(!r)return;r.inHitLibrary=!r.inHitLibrary;save();render();toast(r.inHitLibrary?'已加入爆文库':'已移出爆文库，原素材与拆解结果保留');}
 if(b.dataset.wf==='pinRecord'){const r=state.records.find(r=>r.id===b.dataset.id);r.pinnedAt=r.pinnedAt?null:now();save();render();}
 if(b.dataset.wf==='deleteRecord'){
  const r=state.records.find(r=>r.id===b.dataset.id);if(!r)return;
  lab.trash=lab.trash||[];lab.trash.push({record:r,metrics:lab.metrics.filter(m=>m.recordId===r.id),deletedAt:now()});
  state.records=state.records.filter(x=>x.id!==r.id);lab.metrics=lab.metrics.filter(m=>m.recordId!==r.id);state.selected=state.records[0]?.id;save();render();msg('素材已移入回收站，可从“回收站”恢复。');
 }
 if(b.dataset.wf==='trash')dialog('素材回收站',(lab.trash||[]).map(x=>'<div class="wf-card"><p>'+E(x.record.title)+'</p><button data-wf="restoreRecord" data-id="'+E(x.record.id)+'">恢复素材</button></div>').join('')||'<p>回收站为空</p>');
 if(b.dataset.wf==='restoreRecord'){
  const item=(lab.trash||[]).find(x=>x.record.id===b.dataset.id);if(!item)return;if(state.records.some(r=>r.id===item.record.id))throw Error('该素材已存在');
  state.records.push(item.record);lab.metrics.push(...item.metrics);lab.trash=lab.trash.filter(x=>x!==item);state.selected=item.record.id;state.view='work';save();$('#wfDialog').close();render();toast('素材已恢复');
 }
 }catch(err){toast(err.message)}});
library=function(){
 const matches=state.records.filter(r=>(r.title+r.text+(r.source?.platform||'')).includes(state.query)).slice().sort((a,b)=>String(b.pinnedAt||'').localeCompare(String(a.pinnedAt||'')));
 $('#library').innerHTML=matches.map(r=>'<div class="record '+(r.id===current()?.id?'selected':'')+'"><button data-record="'+E(r.id)+'" style="border:0;background:transparent;text-align:left;padding:0;width:100%"><span class="tag">'+(r.pinnedAt?'📌 置顶 · ':'')+(r.sample?'示例内容':isPending(r)?'待补字幕':'已导入')+'</span><b>'+E(r.title)+'</b><small>'+r.text.length+' 字'+(r.inHitLibrary?' · 已入爆文库':'')+'</small></button><div class="actions" style="margin-top:10px"><button data-wf="pinRecord" data-id="'+E(r.id)+'">'+(r.pinnedAt?'取消置顶':'置顶')+'</button><button data-wf="deleteRecord" data-id="'+E(r.id)+'">删除</button></div></div>').join('')||'<p>没有匹配的内容</p>';
 const cards=$('#library').querySelectorAll('.record');cards.forEach((card,i)=>{const r=matches[i];card.querySelector('.actions').insertAdjacentHTML('beforeend','<button data-wf="toggleHitLibrary" data-id="'+E(r.id)+'">'+(r.inHitLibrary?'移出爆文库':'加入爆文库')+'</button>')});
};
document.querySelector('header .actions')?.insertAdjacentHTML('beforeend','<button data-wf="trash">回收站</button>');


formulas=function(){
 const records=state.records.filter(r=>r.inHitLibrary===true);
 $('#view').innerHTML='<div class="panel pad"><h2>手动精选的爆文公式库</h2><p class="note">仅展示你手动加入的 '+records.length+' 篇素材。可随时移出，原素材和拆解结果会保留；入库不代表数据已达标。</p></div><div class="cards section">'+records.map(r=>{
 const latest=lab.analyses.filter(a=>a.recordIds.includes(r.id)).at(-1)?.result;
 return '<article class="panel topic"><span class="tag">手动入库</span><h3>'+E(r.title)+'</h3><div class="formula">'+E(latest?.values?.[9]||r.manual?.[9]||r.analysis?.values?.[9]||'尚无公式，请先补充正文并拆解')+'</div><p><b>可复用的部分</b><br>'+E(latest?.reuse||r.analysis?.reuse||'待拆解')+'</p><div class="actions"><button data-open="'+E(r.id)+'">查看来源与拆解 →</button><button data-wf="toggleHitLibrary" data-id="'+E(r.id)+'">移出爆文库</button></div></article>';
 }).join('')+'</div>'+(!records.length?'<div class="panel empty section">爆文库还没有素材。在左侧素材卡片点击“加入爆文库”，即可收藏到这里。<p><button data-view="work">去选择素材</button></p></div>':'');
};

document.querySelector('header .actions')?.insertAdjacentHTML('beforeend','<button data-wf="backup">完整项目备份</button><button data-wf="restore">导入项目备份</button><button data-wf="reload">载入最新版本</button><button data-wf="usageHelp">使用说明</button>');
document.addEventListener('click',e=>{if(e.target.closest('[data-wf="usageHelp"]'))dialog('如何使用蓝胖子内容实验室','<p>本工具帮助内容营销团队拆解历史文案、结合投放表现筛选案例，并形成可复用的公式与新选题。</p><ol><li>导入文案：支持 DOCX、文字版 PDF、TXT、Markdown、CSV/TSV、JSON 和字幕。Word/PDF 每文件一篇；文本第一行为标题，多篇用单独一行 --- 分隔。</li><li>查看拆解：先看顶部爆款关键因素，再看十维结构和原文证据。可点“开始拆解”重新生成。</li><li>关联投放数据：粘贴文字或上传截图，核对识别结果后保存。看后搜目标 ≥0.35%，新增 A3 率目标 ≥8%。</li><li>精选案例：在素材卡片点“加入爆文库”，随时可以移出。置顶、删除和回收站恢复也在素材卡片附近。</li><li>投放复盘：查看每篇内容好在哪、差在哪。达人档案：新建名称，导入过往脚本，在每篇下关联数据，查看合作建议。</li><li>完整项目备份：用顶部备份按钮下载 JSON；换电脑或交给同事时导入备份。</li></ol><p>公开版数据只在当前浏览器保存，分享网址不会共享你的素材。图片识别首次需要下载组件。视频链接可收藏并补充字幕，自动抓取和转写需本地服务版。</p><p>当前使用规则和模板分析；关键因素是候选解释，不能仅凭文本确认爆款原因。图片识别后的数字请核对。</p>')});
init();
})();


